const crypto = require('crypto');

function header(headers, name) {
  const match = Object.entries(headers || {}).find(([key]) => key.toLowerCase() === name.toLowerCase());
  return Array.isArray(match?.[1]) ? match[1][0] : match?.[1];
}

function safeCompare(a, b) {
  const left = Buffer.from(String(a || ''));
  const right = Buffer.from(String(b || ''));
  return left.length === right.length && crypto.timingSafeEqual(left, right);
}

const item = $input.first();
const expectedSecret = process.env.N8N_CALLBACK_SECRET;
const providedSecret = header(item.json.headers, 'x-poc-callback-secret');

if (!expectedSecret) {
  throw new Error('CALLBACK_RECEIVED failed: N8N_CALLBACK_SECRET is not configured');
}

if (!safeCompare(expectedSecret, providedSecret)) {
  console.log(JSON.stringify({ stage: 'CALLBACK_RECEIVED', authorized: false }));
  return [
    {
      json: {
        authorized: false,
        ackStatusCode: 403,
        ackText: 'forbidden',
      },
    },
  ];
}

const payload = item.json.body || {};
console.log(
  JSON.stringify({
    stage: 'CALLBACK_RECEIVED',
    authorized: true,
    correlationId: payload.correlation_id,
    jiraIssueKey: payload.jira_issue_key,
    status: payload.status,
  }),
);

return [
  {
    json: {
      authorized: true,
      ackStatusCode: 202,
      ackText: 'accepted',
      ...payload,
    },
  },
];

function docParagraphs(lines) {
  return {
    type: 'doc',
    version: 1,
    content: lines.map((line) => ({
      type: 'paragraph',
      content: line ? [{ type: 'text', text: line }] : [],
    })),
  };
}

function chooseReviewTransition(transitions) {
  const preferred = [/review/i, /ready/i, /qa/i, /done/i, /complete/i];
  return (transitions || []).find((transition) => {
    const label = `${transition.name || ''} ${transition.to?.name || ''}`;
    return preferred.some((pattern) => pattern.test(label));
  });
}

async function jiraFetch(path, options = {}) {
  const response = await fetch(`${process.env.JIRA_BASE_URL.replace(/\/$/, '')}${path}`, {
    ...options,
    headers: {
      Authorization: process.env.JIRA_AUTH_HEADER,
      Accept: 'application/json',
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
  });
  const text = await response.text();
  let data = {};
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = { raw: text.slice(0, 600) };
    }
  }
  if (!response.ok) throw new Error(`Jira ${options.method || 'GET'} ${path} failed (${response.status}): ${text.slice(0, 600)}`);
  return data;
}

const input = $input.first().json;
if (!input.authorized) return [{ json: input }];

try {
  if (!process.env.JIRA_BASE_URL || !process.env.JIRA_AUTH_HEADER) {
    throw new Error('Missing JIRA_BASE_URL or JIRA_AUTH_HEADER');
  }
  const issueKey = input.jira_issue_key;
  const jiraIssueUrl = `${process.env.JIRA_BASE_URL.replace(/\/$/, '')}/browse/${issueKey}`;
  const success = input.status === 'success';
  const lines = success
    ? [
        'Prototype implementation completed.',
        `Correlation ID: ${input.correlation_id}`,
        `Branch: ${input.branch}`,
        `Commit: ${input.commit_sha}`,
        `Build: ${input.build_result || 'unknown'}`,
        `Pull Request: ${input.pr_url}`,
        `Preview: ${input.preview_url}`,
        `Run: ${input.run_url}`,
      ]
    : [
        'Prototype implementation failed.',
        `Correlation ID: ${input.correlation_id}`,
        `Stage: ${input.stage || 'unknown'}`,
        `Build: ${input.build_result || 'failed'}`,
        `Run: ${input.run_url || 'unknown'}`,
        `Error: ${input.error_message || 'Unknown error'}`,
      ];

  await jiraFetch(`/rest/api/3/issue/${encodeURIComponent(issueKey)}/comment`, {
    method: 'POST',
    body: JSON.stringify({ body: docParagraphs(lines) }),
  });

  let reviewTransitionApplied = '';
  if (success) {
    const transitions = await jiraFetch(`/rest/api/3/issue/${encodeURIComponent(issueKey)}/transitions`);
    const reviewTransition = chooseReviewTransition(transitions.transitions);
    if (reviewTransition?.id) {
      await jiraFetch(`/rest/api/3/issue/${encodeURIComponent(issueKey)}/transitions`, {
        method: 'POST',
        body: JSON.stringify({ transition: { id: reviewTransition.id } }),
      });
      reviewTransitionApplied = reviewTransition.name || reviewTransition.to?.name || reviewTransition.id;
    }
  }

  console.log(
    JSON.stringify({
      stage: 'JIRA_COMPLETED',
      correlationId: input.correlation_id,
      jiraIssueKey: issueKey,
      reviewTransitionApplied,
    }),
  );

  return [{ json: { ...input, jiraUpdateOk: true, jira_issue_url: jiraIssueUrl, review_transition_applied: reviewTransitionApplied } }];
} catch (error) {
  return [{ json: { ...input, jiraUpdateOk: false, jiraError: String(error.message || error).slice(0, 900) } }];
}

async function postSlack(channel, threadTs, text) {
  const response = await fetch('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${process.env.SLACK_BOT_TOKEN}`,
      'Content-Type': 'application/json; charset=utf-8',
    },
    body: JSON.stringify({
      channel,
      thread_ts: threadTs,
      unfurl_links: false,
      unfurl_media: false,
      text,
    }),
  });
  const data = await response.json();
  if (!data.ok) throw new Error(`Slack chat.postMessage failed: ${data.error || 'unknown_error'}`);
  return data;
}

const input = $input.first().json;
if (!input.authorized) return [{ json: input }];
if (!process.env.SLACK_BOT_TOKEN) throw new Error('SLACK_COMPLETED failed: SLACK_BOT_TOKEN is not configured');

const success = input.status === 'success';
const jiraUrl = input.jira_issue_url || `${process.env.JIRA_BASE_URL?.replace(/\/$/, '') || ''}/browse/${input.jira_issue_key}`;
const text = success
  ? `${input.jira_issue_key} prototype update ready\n\nPrototype: ${input.preview_url}\nPull Request: ${input.pr_url}\nJira: ${jiraUrl}\n\nBuild: ${input.build_result === 'success' ? 'Passed' : input.build_result}\nCorrelation: ${input.correlation_id}`
  : `${input.jira_issue_key} prototype automation failed\n\nStage: ${input.stage || 'unknown'}\nRun: ${input.run_url || 'unknown'}\nJira: ${jiraUrl}\nBuild: ${input.build_result || 'failed'}\nCorrelation: ${input.correlation_id}\nError: ${input.error_message || 'Unknown error'}`;

await postSlack(input.slack_channel_id, input.slack_thread_ts || input.slack_message_ts, text);
console.log(JSON.stringify({ stage: 'SLACK_COMPLETED', correlationId: input.correlation_id, status: input.status }));

return [{ json: { ...input, slackReplyOk: true } }];
